def fill_missing_versions(apps, schema_editor):
    """Audit item 16. Production had no rows without a version (checked 13 October); any row that
    still has none is given its manuscript's current version before the column becomes required."""
    Manuscript = apps.get_model('review', 'Manuscript')
    for name in ('ReadinessAssessment', 'VenueMatch', 'VenueSubmission'):
        model = apps.get_model('review', name)
        for row in model.objects.filter(version__isnull=True).only('id', 'manuscript_id'):
            current = Manuscript.objects.filter(id=row.manuscript_id).values_list('current_version_id', flat=True).first()
            if current is None:
                raise RuntimeError(f'{name} {row.id} has no version and its manuscript has no current version; '
                                   'fix this row before migrating.')
            model.objects.filter(id=row.id).update(version_id=current)


